$prod->set_manage_stock( false );      /* likuti valdo partijos (FEFO) */
/* PVM: naujos prekes VISADA `taxable`. S654 pamoka — penki importo
   profiliai buvo palike `none`, ir 988 prekes checkout'e ejo be PVM. */
$prod->set_tax_status( 'taxable' );
if ( $kaina > 0 ) { $prod->set_regular_price( (string) $kaina ); }
if ( $apras !== '' ) { $prod->set_description( $apras ); }
if ( $trumpas !== '' ) { $prod->set_short_description( $trumpas ); }
if ( $svoris > 0 ) { $prod->set_weight( (string) $svoris ); }
foreach ( array( 'ilgis' => 'set_length', 'plotis' => 'set_width', 'aukstis' => 'set_height' ) as $r => $m ) {
	$v = isset( $matmenys[ $r ] ) ? self::skaicius( $matmenys[ $r ] ) : 0;
	if ( $v > 0 ) { $prod->{$m}( (string) $v ); }
}
if ( $katai ) { $prod->set_category_ids( $katai ); }
if ( $galerija ) { $prod->set_gallery_image_ids( $galerija ); }
$pid = $prod->save();

if ( ! $pid ) { wp_send_json_error( 'nepavyko sukurti prekės' ); }

/* AV sandelis — be sios zymes preke neatsirastu nei partijose, nei
   savo eilese, o gavimas butu beprasmis. */
update_post_meta( $pid, '_ps_sandelis', 'av' ); /* S1705: mazosios — kaip visur sistemoje */
if ( $ean !== '' ) {
	update_post_meta( $pid, '_ean', $ean );
	update_post_meta( $pid, '_global_unique_id', $ean );
}
if ( $foto > 0 && get_post_type( $foto ) === 'attachment' ) { set_post_thumbnail( $pid, $foto ); }

/* Taksonomijos — TIK per term_id (slug kolizija: „1,5 kg" ir „15 kg"
   sanitizuojasi i ta pati „15-kg"). */
$tax_map = array(
	'brendas'       => 'product_brand',
	'gyvuno_rusis'  => 'pa_gyvuno_rusis',
	'pakuotes_dydis'=> 'pa_pakuotes_dydis',
);
foreach ( $tax_map as $raktas => $tax ) {
	$tid = isset( $d[ $raktas ] ) ? (int) $d[ $raktas ] : 0;
	if ( ! $tid || ! taxonomy_exists( $tax ) ) { continue; }
	$t = get_term( $tid );
	if ( ! $t || is_wp_error( $t ) || $t->taxonomy !== $tax ) { continue; }
	wp_set_object_terms( $pid, array( $tid ), $tax, false );
	if ( strpos( $tax, 'pa_' ) === 0 ) {
		/* Taksonominis atributas neissilaiko be registracijos
		   `_product_attributes` — WC naktį nusalintu orphan rysius. */
		$reg = get_post_meta( $pid, '_product_attributes', true );
		if ( ! is_array( $reg ) ) { $reg = array(); }
		$reg[ $tax ] = array( 'name' => $tax, 'value' => '', 'position' => count( $reg ),
			'is_visible' => 1, 'is_variation' => 0, 'is_taxonomy' => 1 );
		update_post_meta( $pid, '_product_attributes', $reg );
	}
}

/* v1.4: patvirtinti atributu pasiulymai. Priskiriami TIK tie, kuriuos
   zmogus paliko pazymetus — parseris siulo, sprendzia zmogus. */
if ( ! empty( $d['atributai'] ) && is_array( $d['atributai'] ) ) {
	foreach ( $d['atributai'] as $tax => $terminai ) {
		$tax = sanitize_key( $tax );
		if ( ! taxonomy_exists( $tax ) || strpos( $tax, 'pa_' ) !== 0 ) { continue; }
		$ids = array_values( array_filter( array_map( 'intval', (array) $terminai ) ) );
		if ( ! $ids ) { continue; }
		$ok = array();
		foreach ( $ids as $tid ) {
			$t = get_term( $tid );
			if ( $t && ! is_wp_error( $t ) && $t->taxonomy === $tax ) { $ok[] = $tid; }
		}
		if ( ! $ok ) { continue; }
		wp_set_object_terms( $pid, $ok, $tax, false );
		$reg = get_post_meta( $pid, '_product_attributes', true );
		if ( ! is_array( $reg ) ) { $reg = array(); }
		$reg[ $tax ] = array( 'name' => $tax, 'value' => '', 'position' => count( $reg ),
			'is_visible' => 1, 'is_variation' => 0, 'is_taxonomy' => 1 );
		update_post_meta( $pid, '_product_attributes', $reg );
	}
}

/* Busena: pilna preke keliauja i prekyba is karto, nepilna — lieka
   juodrastyje su ivardyta priezastimi. Ta pati taisykle, kaip
   `petshop-vartai.php` taiko VF ir ZB prekems. */
$truksta = array();
if ( $kaina <= 0 ) { $truksta[] = 'nėra kainos'; }
if ( ! $katai ) { $truksta[] = 'nėra kategorijos'; }
if ( $foto <= 0 ) { $truksta[] = 'nėra nuotraukos'; }
if ( mb_strlen( trim( wp_strip_all_tags( $apras ) ) ) < 120 ) { $truksta[] = 'nėra aprašymo'; }

if ( ! $truksta ) {
	wp_update_post( array( 'ID' => $pid, 'post_status' => 'publish' ) );
	update_post_meta( $pid, '_ps_publikuota', current_time( 'mysql' ) );
} else {
	update_post_meta( $pid, '_ps_i_juodrasti', implode( ', ', $truksta ) . ' · ' . current_time( 'mysql' ) );
}

if ( class_exists( 'Petshop_Pilnumas' ) ) { Petshop_Pilnumas::perskaiciuoti( $pid ); }
if ( function_exists( 'wc_delete_product_transients' ) ) { wc_delete_product_transients( $pid ); }

if ( class_exists( 'Petshop_Ivykiai' ) && method_exists( 'Petshop_Ivykiai', 'irasyti' ) ) {
	try { Petshop_Ivykiai::irasyti( $pid, 'sukurta', array(
		'laukas' => 'gavimas', 'buvo' => '', 'tapo' => $pav . ' · ' . $sku ) ); }
	catch ( Throwable $e ) { /* zurnalas neprivalo blokuoti */ }
}

wp_send_json_success( array(
	'id'      => (int) $pid,
	'pav'     => $pav,
	'sku'     => $sku,
	'ean'     => $ean,
	'busena'  => $truksta ? 'draft' : 'publish',
	'truksta' => $truksta,
	'av'      => 0,
	'sav'     => '',
	'sand'    => 'av',
	'av_preke'=> true,
